<script id="rampart-strategy">
function createStrategy() {
  // Crossroads carry clustered ground traffic. Reserve two lane batteries for flyers.
  const order = [1,6,7,5,11,2,3,8,12,4,13,10,0,9,14,15];
  const types = ['"'cannon','cannon','cannon','flak','cannon','cannon','cannon','cannon','cannon','cannon','cannon','flak','cannon','cannon','cannon','flak'];
  return {
    plan(s) {
      let gold=s.gold, actions=[];
      const tiers=s.slots.map(v=>v.turret?v.turret.tier:0);
      for(let step=0;step<32;step++){
        let choice=-1, best=-1;
        for(let i=0;i<16;i++){
          const tier=tiers[order[i]], air=types[i]==='flak', cost=(air?80:90)*(tier===2?2:1);
          if(tier===3 || (air && s.wave<3)) continue;
          const priority=(1-i*.052)*(tier===0?1:tier===1?.80:.58)*(air&&i===3?1.25:1);
          if(priority>best){best=priority;choice=i;}
        }
        if(choice<0)break;
        const slot=order[choice],type=types[choice],tier=tiers[slot],cost=(type==='flak'?80:90)*(tier===2?2:1);
        if(gold<cost)break;
        gold-=cost;actions.push(tier?{op:'upgrade',slot}:{op:'build',slot,type});tiers[slot]++;
      }
      return actions;
    },
    target(t,c) {
      const radius=t.type==='flak'?70:90, damage=(t.type==='flak'?[40,64,102]:[60,96,153])[t.tier-1];
      let best=-1,id=c[0].id;
      for(const a of c){
        let value=0;
        for(const b of c){
          const dx=a.x-b.x,dy=a.y-b.y;
          if(dx*dx+dy*dy>radius*radius)continue;
          const dmg=Math.max(1,damage-b.armor);
          value+=(Math.min(b.hp,dmg)/damage+(b.hp<=dmg?.38:0))*(1+15000/(150+b.remaining/b.speed)**2)*(b.type==='mender'?1.45:1);
        }
        value+=.04/(1+a.remaining/100);
        if(value>best){best=value;id=a.id;}
      }
      return id;
    }
  };
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const recorder=arguments[3], strategy=createStrategy(), log=[];
  const slots=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]].map(([x,y],slot)=>({slot,x:x*100+50,y:y*100+50,turret:null}));
  const ground=[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],air=[[0,6],[21,6],[21,11],[23,11]];
  const towers=['bolt','cannon','frost','lance','flak'],cost=[50,90,70,120,80],damage=[26,60,10,180,40],period=[8,24,12,36,10],range=[300,260,240,360,320],splash=[0,90,0,0,70];
  const names=['grunt','runner','wisp','brute','splitter','mender','splitling'], hp=[60,40,50,150,90,70],speed=[10,20,12,6,8,8,12],bounty=[4,4,6,9,6,7,1],leak=[1,1,2,3,2,2,1], first=[1,2,3,4,6,8],weight=[10,4,3,3,2,1];
  const floor=Math.floor;
  function draw(){seed=(seed+0x6D2B79F5)|0;let t=Math.imul(seed"'^(seed>>>15),1|seed);t=(t+Math.imul(t''^(t>>>7),61|t))''^t;return(t''^(t>>>14))>>>0;}
  function waveList(w){let sum=0;for(let i=0;i<6;i++)if(first[i]<=w)sum+=weight[i];return Array.from({length:4+floor(3*w/5)},()=>{let r=draw()%sum,i=0;while(r>=weight[i])r-=weight[i++];return i;});}
  let next=waveList(1), wave=0,gold=250,baseHp=10,tick=0,fallTick=-1,serial=0,enemies=[],queue=[],scale=1000;
  function emit(kind,...args){if(recorder)recorder.event(tick,kind,...args);}
  function position(e){
    let d=e.progress,p=e.air?air:ground;
    for(let i=1;i<p.length;i++){
      const [x,y]=p[i-1],dx=p[i][0]-x,dy=p[i][1]-y,len=(Math.abs(dx)+Math.abs(dy))*100;
      if(d<=len){e.x=x*100+50+Math.sign(dx)*d;e.y=y*100+50+Math.sign(dy)*d;e.dir=Math.atan2(dx,dy);return;}d-=len;
    }
  }
  function spawn(i,w,maxHp,progress=0){
    const flyer=+(i===2), e={id:++serial,type:names[i],i,w,hp:maxHp,maxHp,x:0,y:0,air:flyer,armor:i===0?floor(w/4):i===3?6+w:0,speed:speed[i],slowed:0,remaining:(flyer?2600:4600)-progress,progress,age:0};
    position(e);enemies.push(e);
  }
  function view(e){const {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining}=e;return {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining};}
  function near(a,b,r){return (a.x-b.x)**2+(a.y-b.y)**2<=r*r;}
  function record(){if(recorder)recorder.frame(tick,wave,gold,baseHp,next,slots,enemies);}
  for(;tick<maxTicks;tick++){
    if(tick>=20&&(tick-20)%40===0){
      wave++;if(wave>1)scale=floor(scale*108/100);
      gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
      const current=next;next=waveList(wave+1);
      const state={tick,wave,gold,baseHp,slots:slots.map(({slot,x,y,turret:t})=>({slot,x,y,turret:t?{type:t.type,tier:t.tier,spent:t.spent}:null})),enemies:enemies.map(view),nextWave:next.map(i=>names[i])};
      emit('"'wave');
      for(const a of (strategy.plan(state)||[]).slice(0,32)){
        if("'!a||!Number.isInteger(a.slot)||!slots[a.slot])continue;
        const sl=slots[a.slot],t=sl.turret,i=towers.indexOf(a.type);
        if(a.op==='"'build'&&"'!t&&i>=0&&gold>=cost[i]){
          gold-=cost[i];sl.turret={i,type:a.type,tier:1,spent:cost[i],cd:0};log.push([tick,'"'B',sl.slot,i]);emit('build',sl.slot);
        }else if(a.op==='upgrade'&&t&&t.tier<3&&gold>=cost[t.i]*t.tier){
          const price=cost[t.i]*t.tier;gold-=price;t.spent+=price;t.tier++;log.push([tick,'U',sl.slot,t.tier]);emit('upgrade',sl.slot);
        }else if(a.op==='sell'&&t){gold+=floor(t.spent*7/10);sl.turret=null;log.push([tick,'S',sl.slot,0]);emit('sell',sl.slot);}
      }
      current.forEach((i,n)=>queue.push({at:tick+4*n,i,w:wave,h:floor(hp[i]*scale/1000),n}));
      queue.sort((a,b)=>a.at-b.at||a.w-b.w||a.n-b.n);
    }
    while(queue.length&&queue[0].at===tick){const q=queue.shift();spawn(q.i,q.w,q.h);}
    for(const e of enemies){
      const step=e.slowed?floor(e.speed*.6):e.speed;e.progress+=step;e.remaining-=step;
      if(e.remaining<=0){e.gone=true;baseHp-=leak[e.i];log.push([tick,'L',e.id,baseHp]);emit('leak',e.id);if(baseHp<=0){fallTick=tick;log.push([tick,'F',wave,0]);emit('fall');break;}}else position(e);
    }
    enemies=enemies.filter(e=>"'!e.gone);
    if(fallTick>=0){record();break;}
    for(const e of enemies){e.age++;if(e.i===5&&e.age%20===0){for(const b of enemies)if(near(e,b,150))b.hp=Math.min(b.maxHp,b.hp+floor(b.maxHp*8/100));emit('"'heal',e.x,e.y);}}
    for(const sl of slots){
      const t=sl.turret;if("'!t||(t.cd>0&&--t.cd>0))continue;
      const i=t.i,r=range[i]+30*(t.tier-1),can=e=>e.air?(i===0||i===2||i===4):i!==4;
      const candidates=enemies.filter(e=>can(e)&&near(sl,e,r));if(!candidates.length)continue;
      const id=strategy.target?.({slot:sl.slot,type:t.type,tier:t.tier,x:sl.x,y:sl.y,range:r},candidates.map(view));
      const target=candidates.find(e=>e.id===id)||candidates.reduce((a,b)=>a.remaining<=b.remaining?a:b);
      let dmg=damage[i];for(let j=1;j<t.tier;j++)dmg=floor(dmg*16/10);
      emit('"'shot',sl.slot,i,target.x,target.y,target.air);t.cd=period[i];
      for(const b of splash[i]?enemies:[target]){
        if(splash[i]&&("'!can(b)||!near(target,b,splash[i])))continue;
        b.hp-=Math.max(1,dmg-(i===3?0:b.armor));if(i===2)b.slowed=30;
      }
      const dead=enemies.filter(e=>e.hp<=0);
      if(dead.length)enemies=enemies.filter(e=>e.hp>0);
      for(const e of dead){gold+=bounty[e.i];log.push([tick,'"'K',e.id,sl.slot]);emit('kill',e.x,e.y,e.i,e.id);if(e.i===4)for(let n=0;n<3;n++)spawn(6,e.w,Math.max(1,floor(e.maxHp/4)),e.progress);}
    }
    for(const e of enemies)if(e.slowed)e.slowed--;
    record();
  }
  let hash=0x811c9dc5;const str=JSON.stringify(log);for(let i=0;i<str.length;i++)hash=Math.imul(hash"'^str.charCodeAt(i),0x01000193);
  return {score:Math.round((tick-20)/40*100)/100,fallTick,log,hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
</script>
