import re, subprocess
s=open('index.html').read()
js='\\n'.join(re.findall(r'<script id=\"rampart-(?:strategy|sim)\">(.*?)</script>',s,re.S))
js+=\"\"\"
const A=()=>({plan(s){let g=s.gold,a=[];for(const sl of s.slots)if("'!sl.turret&&g>=50){a.push({op:'"'build',slot:sl.slot,type:'bolt'});g-=50;}return a;}});
const B=()=>({plan(s){return ({1:[{op:\"build\",slot:3,type:\"cannon\"},{op:\"build\",slot:6,type:\"frost\"}],3:[{op:\"upgrade\",slot:3},{op:\"build\",slot:12,type:\"flak\"}],6:[{op:\"build\",slot:8,type:\"lance\"},{op:\"sell\",slot:6}]})[s.wave]||[];}});
for(let [str,seed] of [[A,42],[B,7],...[1,2,3,4,5,6,7,8,42].map(i=>[createStrategy,i])]){let r=rampartSimulate(str,seed,12020);print(seed,r.score,r.fallTick,r.hash,r.log.length);}
\"\"\"
open('/tmp/ramparttest.js','w').write(js)
subprocess.run(['/System/Library/Frameworks/JavaScriptCore.framework/Versions/A/Helpers/jsc','/tmp/ramparttest.js'])
