function createStrategy() {
  // Crossroads carry clustered ground traffic. Reserve two lane batteries for flyers.
  const order = [1,6,7,5,11,2,3,8,12,4,13,10,0,9,14,15];
  const types = ['"'cannon','cannon','cannon','flak','cannon','cannon','cannon','cannon','cannon','cannon','cannon','flak','cannon','cannon','cannon','flak'];
  return {
    plan(s) {
      let gold=s.gold, actions=[];
      const tiers=s.slots.map(v=>v.turret?v.turret.tier:0);
      for(let step=0;step<32;step++){
        let choice=-1, best=-1;
        for(let i=0;i<16;i++){
          const tier=tiers[order[i]], air=types[i]==='flak', cost=(air?80:90)*(tier===2?2:1);
          if(tier===3 || (air && s.wave<3)) continue;
          const priority=(1-i*.052)*(tier===0?1:tier===1?.80:.58)*(air&&i===3?1.25:1);
          if(priority>best){best=priority;choice=i;}
        }
        if(choice<0)break;
        const slot=order[choice],type=types[choice],tier=tiers[slot],cost=(type==='flak'?80:90)*(tier===2?2:1);
        if(gold<cost)break;
        gold-=cost;actions.push(tier?{op:'upgrade',slot}:{op:'build',slot,type});tiers[slot]++;
      }
      return actions;
    },
    target(t,c) {
      const radius=t.type==='flak'?70:90, damage=(t.type==='flak'?[40,64,102]:[60,96,153])[t.tier-1];
      let best=-1,id=c[0].id;
      for(const a of c){
        let value=0;
        for(const b of c){
          const dx=a.x-b.x,dy=a.y-b.y;
          if(dx*dx+dy*dy>radius*radius)continue;
          const dmg=Math.max(1,damage-b.armor);
          value+=(Math.min(b.hp,dmg)/damage+(b.hp<=dmg?.38:0))*(1+15000/(150+b.remaining/b.speed)**2)*(b.type==='mender'?1.45:1);
        }
        value+=.04/(1+a.remaining/100);
        if(value>best){best=value;id=a.id;}
      }
      return id;
    }
  };
}
